/**
 * NKPDF 2.9 — Pure ES5 MQTT v3.1.1 over WebSocket Client (vendor/mqtt.min.js)
 * Tương thích 100% với Samsung Tizen Smart TV, LG WebOS, Android TV và iPadOS Safari.
 * Không phụ thuộc CDN ngoài, không dùng cú pháp ES2020 (?. / ?? / BigInt) gây lỗi trên TV.
 */
(function (global) {
  'use strict';

  function utf8ToBytes(str) {
    if (typeof TextEncoder !== 'undefined') {
      return new TextEncoder().encode(str);
    }
    var utf8 = unescape(encodeURIComponent(str));
    var arr = new Uint8Array(utf8.length);
    for (var i = 0; i < utf8.length; i++) {
      arr[i] = utf8.charCodeAt(i);
    }
    return arr;
  }

  function bytesToUtf8(bytes) {
    if (typeof TextDecoder !== 'undefined') {
      return new TextDecoder('utf-8').decode(bytes);
    }
    var bin = '';
    var chunk = 8192;
    for (var i = 0; i < bytes.length; i += chunk) {
      var sub = bytes.subarray(i, Math.min(bytes.length, i + chunk));
      bin += String.fromCharCode.apply(null, sub);
    }
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }

  function encodeRemainingLength(len) {
    var out = [];
    do {
      var digit = len % 128;
      len = Math.floor(len / 128);
      if (len > 0) digit = digit | 0x80;
      out.push(digit);
    } while (len > 0);
    return out;
  }

  function decodeRemainingLength(buf, offset) {
    var multiplier = 1;
    var value = 0;
    var idx = offset;
    var encodedByte;
    do {
      if (idx >= buf.length) return null;
      encodedByte = buf[idx++];
      value += (encodedByte & 127) * multiplier;
      if (multiplier > 128 * 128 * 128) return { error: 'Malformed Remaining Length' };
      multiplier *= 128;
    } while ((encodedByte & 128) !== 0);
    return { value: value, nextOffset: idx };
  }

  function buildConnectPacket(clientId, keepaliveSec) {
    var idBytes = utf8ToBytes(clientId);
    var ka = keepaliveSec || 30;
    // Variable header: "MQTT" (6 bytes) + level 4 (1) + flags 0x02 clean session (1) + keepalive (2) = 10 bytes
    var remLen = 10 + 2 + idBytes.length;
    var rlBytes = encodeRemainingLength(remLen);
    var pkt = new Uint8Array(1 + rlBytes.length + remLen);
    var p = 0;
    pkt[p++] = 0x10; // CONNECT
    for (var i = 0; i < rlBytes.length; i++) pkt[p++] = rlBytes[i];
    // Protocol Name "MQTT"
    pkt[p++] = 0x00; pkt[p++] = 0x04;
    pkt[p++] = 0x4D; pkt[p++] = 0x51; pkt[p++] = 0x54; pkt[p++] = 0x54;
    pkt[p++] = 0x04; // Protocol level 4 (MQTT 3.1.1)
    pkt[p++] = 0x02; // Clean session
    pkt[p++] = (ka >> 8) & 0xFF;
    pkt[p++] = ka & 0xFF;
    // Payload: Client ID
    pkt[p++] = (idBytes.length >> 8) & 0xFF;
    pkt[p++] = idBytes.length & 0xFF;
    pkt.set(idBytes, p);
    return pkt;
  }

  function buildSubscribePacket(packetId, topic) {
    var tBytes = utf8ToBytes(topic);
    var remLen = 2 + 2 + tBytes.length + 1;
    var rlBytes = encodeRemainingLength(remLen);
    var pkt = new Uint8Array(1 + rlBytes.length + remLen);
    var p = 0;
    pkt[p++] = 0x82; // SUBSCRIBE (QoS 1 required by spec)
    for (var i = 0; i < rlBytes.length; i++) pkt[p++] = rlBytes[i];
    pkt[p++] = (packetId >> 8) & 0xFF;
    pkt[p++] = packetId & 0xFF;
    pkt[p++] = (tBytes.length >> 8) & 0xFF;
    pkt[p++] = tBytes.length & 0xFF;
    pkt.set(tBytes, p);
    p += tBytes.length;
    pkt[p++] = 0x00; // Requested QoS 0
    return pkt;
  }

  function buildPublishPacket(topic, payloadStr) {
    var tBytes = utf8ToBytes(topic);
    var pBytes = utf8ToBytes(payloadStr);
    var remLen = 2 + tBytes.length + pBytes.length;
    var rlBytes = encodeRemainingLength(remLen);
    var pkt = new Uint8Array(1 + rlBytes.length + remLen);
    var p = 0;
    pkt[p++] = 0x30; // PUBLISH QoS 0
    for (var i = 0; i < rlBytes.length; i++) pkt[p++] = rlBytes[i];
    pkt[p++] = (tBytes.length >> 8) & 0xFF;
    pkt[p++] = tBytes.length & 0xFF;
    pkt.set(tBytes, p);
    p += tBytes.length;
    pkt.set(pBytes, p);
    return pkt;
  }

  function MqttClient(url, options) {
    var self = this;
    options = options || {};
    self.url = url;
    self.clientId = options.clientId || ('nkpdf_' + Math.random().toString(16).slice(2, 10));
    self.connectTimeout = options.connectTimeout || 6500;
    self.keepalive = options.keepalive || 25;
    self.connected = false;
    self.ended = false;
    self._listeners = {};
    self._subCallbacks = {};
    self._nextPktId = 1;
    self._ws = null;
    self._connTimer = null;
    self._pingTimer = null;
    self._rxBuf = new Uint8Array(0);

    self._start();
  }

  MqttClient.prototype.on = function (ev, fn) {
    if (!this._listeners[ev]) this._listeners[ev] = [];
    this._listeners[ev].push(fn);
    return this;
  };

  MqttClient.prototype._emit = function (ev, a, b, c) {
    var list = this._listeners[ev];
    if (!list) return;
    for (var i = 0; i < list.length; i++) {
      try { list[i](a, b, c); } catch (e) {}
    }
  };

  MqttClient.prototype._clearTimers = function () {
    if (this._connTimer) { clearTimeout(this._connTimer); this._connTimer = null; }
    if (this._pingTimer) { clearInterval(this._pingTimer); this._pingTimer = null; }
  };

  MqttClient.prototype._start = function () {
    var self = this;
    if (self.ended) return;
    self._clearTimers();

    self._connTimer = setTimeout(function () {
      if (!self.connected && !self.ended) {
        var err = new Error('Timeout (' + self.connectTimeout + 'ms) khi kết nối ' + self.url);
        err.code = 'ETIMEDOUT';
        self._emit('timeout', err);
        self._emit('error', err);
        self.end(true);
      }
    }, self.connectTimeout);

    var ws;
    try {
      ws = new WebSocket(self.url, 'mqtt');
    } catch (e) {
      self._clearTimers();
      setTimeout(function () {
        self._emit('error', e);
        self._emit('close', e);
      }, 10);
      return;
    }

    ws.binaryType = 'arraybuffer';
    self._ws = ws;

    ws.onopen = function () {
      if (self.ended) {
        try { ws.close(); } catch (e) {}
        return;
      }
      try {
        ws.send(buildConnectPacket(self.clientId, self.keepalive));
      } catch (err) {
        self._emit('error', err);
      }
    };

    ws.onmessage = function (ev) {
      if (self.ended || !ev || !ev.data) return;
      var chunk = new Uint8Array(ev.data);
      if (self._rxBuf.length === 0) {
        self._rxBuf = chunk;
      } else {
        var merged = new Uint8Array(self._rxBuf.length + chunk.length);
        merged.set(self._rxBuf, 0);
        merged.set(chunk, self._rxBuf.length);
        self._rxBuf = merged;
      }
      self._processRxBuffer();
    };

    ws.onerror = function () {
      if (self.ended) return;
      var err = new Error('Lỗi kết nối WebSocket tới ' + self.url);
      err.code = 'EWSERROR';
      self._emit('error', err);
    };

    ws.onclose = function (ev) {
      var wasConnected = self.connected;
      self.connected = false;
      self._clearTimers();
      if (self.ended) return;
      if (wasConnected) {
        self._emit('offline');
      }
      self._emit('close', ev);
    };
  };

  MqttClient.prototype._processRxBuffer = function () {
    var self = this;
    while (self._rxBuf.length >= 2) {
      var headerByte = self._rxBuf[0];
      var cmd = headerByte & 0xF0;
      var rl = decodeRemainingLength(self._rxBuf, 1);
      if (!rl) return; // Chưa nhận đủ các byte độ dài
      if (rl.error) {
        self._rxBuf = new Uint8Array(0);
        self._emit('error', new Error(rl.error));
        return;
      }
      var pktTotalLen = rl.nextOffset + rl.value;
      if (self._rxBuf.length < pktTotalLen) return; // Chờ thêm chunk tiếp theo

      var body = self._rxBuf.subarray(rl.nextOffset, pktTotalLen);
      self._rxBuf = self._rxBuf.subarray(pktTotalLen);

      if (cmd === 0x20) {
        // CONNACK
        var rc = body.length >= 2 ? body[1] : 255;
        if (rc === 0) {
          self.connected = true;
          if (self._connTimer) { clearTimeout(self._connTimer); self._connTimer = null; }
          self._pingTimer = setInterval(function () {
            if (self.connected && self._ws && self._ws.readyState === 1) {
              try { self._ws.send(new Uint8Array([0xC0, 0x00])); } catch (e) {}
            }
          }, (self.keepalive * 800));
          self._emit('connect', { returnCode: 0 });
        } else {
          var cErr = new Error('Broker từ chối kết nối (CONNACK code ' + rc + ')');
          self._emit('error', cErr);
          self.end(true);
        }
      } else if (cmd === 0x90) {
        // SUBACK
        if (body.length >= 2) {
          var pid = (body[0] << 8) | body[1];
          var cb = self._subCallbacks[pid];
          if (cb) {
            delete self._subCallbacks[pid];
            try { cb(null); } catch (e) {}
          }
        }
      } else if (cmd === 0x30) {
        // PUBLISH
        if (body.length >= 2) {
          var tLen = (body[0] << 8) | body[1];
          if (body.length >= 2 + tLen) {
            var topicStr = bytesToUtf8(body.subarray(2, 2 + tLen));
            var qos = (headerByte >> 1) & 0x03;
            var payStart = 2 + tLen + (qos > 0 ? 2 : 0);
            if (payStart <= body.length) {
              var payBytes = body.subarray(payStart);
              var payStr = bytesToUtf8(payBytes);
              var payloadWrapper = {
                toString: function () { return payStr; },
                raw: payBytes
              };
              self._emit('message', topicStr, payloadWrapper);
            }
          }
        }
      }
    }
  };

  MqttClient.prototype.subscribe = function (topic, cb) {
    if (!this.connected || !this._ws || this._ws.readyState !== 1) {
      if (cb) cb(new Error('Chưa kết nối Broker'));
      return this;
    }
    var pid = this._nextPktId++;
    if (this._nextPktId > 65000) this._nextPktId = 1;
    if (cb) this._subCallbacks[pid] = cb;
    try {
      this._ws.send(buildSubscribePacket(pid, topic));
    } catch (e) {
      if (cb) {
        delete this._subCallbacks[pid];
        cb(e);
      }
    }
    return this;
  };

  MqttClient.prototype.publish = function (topic, message, opts, cb) {
    if (typeof opts === 'function') { cb = opts; opts = {}; }
    if (!this.connected || !this._ws || this._ws.readyState !== 1) {
      if (cb) cb(new Error('Chưa kết nối Broker'));
      return this;
    }
    var str = typeof message === 'string' ? message : String(message);
    try {
      this._ws.send(buildPublishPacket(topic, str));
      if (cb) cb(null);
    } catch (e) {
      if (cb) cb(e);
    }
    return this;
  };

  MqttClient.prototype.end = function (force) {
    this.ended = true;
    this.connected = false;
    this._clearTimers();
    this._subCallbacks = {};
    if (this._ws) {
      var ws = this._ws;
      this._ws = null;
      try {
        if (!force && ws.readyState === 1) {
          ws.send(new Uint8Array([0xE0, 0x00])); // DISCONNECT
        }
      } catch (e) {}
      try {
        ws.onopen = null;
        ws.onmessage = null;
        ws.onerror = null;
        ws.onclose = null;
        ws.close();
      } catch (e) {}
    }
    return this;
  };

  global.mqtt = {
    version: '2.9.0-es5-tv',
    connect: function (url, options) {
      return new MqttClient(url, options);
    }
  };
})(typeof window !== 'undefined' ? window : globalThis);
